#include <zlib.h>

int Zlib::NormalUncompress(uint8_t* dest, uint32_t* destLen, 
                           const uint8_t* source, uint32_t sourceLen) {
    if (sourceLen == 0 || !dest || !destLen || !source) {
        return -1;
    }

    z_stream strm;
    memset(&strm, 0, sizeof(strm));

    strm.zalloc = Z_NULL;
    strm.zfree = Z_NULL;
    strm.opaque = Z_NULL;
    strm.avail_in = static_cast<z_size_t>(sourceLen);
    strm.next_in = reinterpret_cast<const Bytef*>(source);
